#!/bin/bash
# Generate ALL StudyVance brand assets (images + English audio).
cd /home/z/my-project
BRAND="Flat vector, navy blue turquoise bright yellow white palette, white background, no text, children educational app style."
g() { if [ ! -f "$2" ] || [ $(stat -c%s "$2" 2>/dev/null||echo 0) -lt 1000 ]; then echo "[img] $2..."; timeout 120 z-ai image -p "$1" -o "$2" -s "${3:-1024x1024}" 2>&1|tail -1; sleep 2; else echo "[skip] $2"; fi; }
t() { if [ ! -f "$2" ] || [ $(stat -c%s "$2" 2>/dev/null||echo 0) -lt 1000 ]; then echo "[tts] $2..."; timeout 60 z-ai tts -i "$1" -o "$2" -v jam -s 0.9 -f wav 2>&1|tail -1; sleep 2; else echo "[skip] $2"; fi; }
echo "=== Images ==="
g "A friendly cartoon robot mascot, round navy-blue head, turquoise antenna, bright-yellow eyes, white body with turquoise chest panel. $BRAND" public/assets/mascot/vance-robot.png 1024x1024
g "Wide hero kids AI academy welcome, friendly navy-blue robot mascot waves, floating turquoise yellow shapes, cartoon planets. $BRAND" public/assets/illustrations/welcome-hero.png 1344x768
g "Cartoon robot mascot looks at four cat pictures, thought bubble with question mark. $BRAND" public/assets/illustrations/m1-scene1.png 1344x768
g "Cartoon split: left calculator and kitchen timer, right robot mascot analysing animal photos. $BRAND" public/assets/illustrations/m1-scene2.png 1344x768
g "Cartoon robot mascot holds yellow shield with turquoise lock, protecting floating icons. $BRAND" public/assets/illustrations/m1-scene3.png 1344x768
g "Cartoon robot mascot cheering with confetti, badge with star. $BRAND" public/assets/illustrations/m1-scene4.png 1344x768
g "Cartoon icon of a calculator. $BRAND" public/assets/illustrations/sort-calculator.png 1024x1024
g "Cartoon icon of a kitchen timer. $BRAND" public/assets/illustrations/sort-timer.png 1024x1024
g "Cartoon cat recognised by AI scanner with dashed bounding box. $BRAND" public/assets/illustrations/sort-cat.png 1024x1024
g "Cartoon open storybook with floating text shapes and star. $BRAND" public/assets/illustrations/sort-story.png 1024x1024
g "Cartoon robot mascot pointing at prompt card with personal details highlighted. $BRAND" public/assets/illustrations/privacy-scene.png 1344x768
for i in 1 2 3 4 5 6; do
  case $i in 1) d="curly hair and round glasses";; 2) d="short hair and a yellow headband";; 3) d="braided hair and a turquoise beanie";; 4) d="a buzz cut and bright yellow t-shirt";; 5) d="two pigtails and a yellow star hairclip";; 6) d="wearing a turquoise hoodie and a big smile";; esac
  g "Cartoon avatar of a happy child with $d, friendly smile. $BRAND" public/assets/avatars/avatar-$i.png 1024x1024
done
for m in 1 2 3 4 5 6; do
  case $m in 1) ic="robot head";; 2) ic="yellow question mark speech bubble";; 3) ic="turquoise magnifying glass";; 4) ic="yellow pencil and star";; 5) ic="turquoise lightbulb";; 6) ic="yellow trophy";; esac
  g "Cartoon achievement badge round badge with $ic icon, yellow star border, navy ribbon. $BRAND" public/assets/badges/badge-m$m.png 1024x1024
done
g "Cartoon graduation badge with large yellow star, turquoise ribbon, navy border, sparkles. $BRAND" public/assets/badges/badge-completion.png 1024x1024
echo "=== M2-M6 illustrations ==="
g "Cartoon robot mascot holds speech bubble divided into three sections. $BRAND" public/assets/illustrations/m2-scene1.png 1344x768
g "Cartoon robot mascot stacks three blocks into tower with star. $BRAND" public/assets/illustrations/m2-scene2.png 1344x768
g "Cartoon robot mascot holds two speech bubbles one grey one turquoise. $BRAND" public/assets/illustrations/m2-scene3.png 1344x768
g "Cartoon robot mascot detective with magnifying glass examining cards. $BRAND" public/assets/illustrations/m3-scene1.png 1344x768
g "Cartoon Moon with four turquoise fact cards, robot mascot pointing. $BRAND" public/assets/illustrations/m3-scene2.png 1344x768
g "Cartoon four steps Read Compare Decide Correct, robot mascot walking. $BRAND" public/assets/illustrations/m3-scene3.png 1344x768
g "Cartoon four story planning cards 2x2 grid, robot mascot. $BRAND" public/assets/illustrations/m4-scene1.png 1344x768
g "Cartoon story draft paper with three red X marks, robot mascot. $BRAND" public/assets/illustrations/m4-scene2.png 1344x768
g "Cartoon robot mascot holding checklist with three options, checkmark on honest. $BRAND" public/assets/illustrations/m4-scene3.png 1344x768
g "Cartoon robot mascot on stepping stone crossing stream. $BRAND" public/assets/illustrations/m5-scene1.png 1344x768
g "Cartoon robot mascot at blackboard showing 3x7=21 red X and 3x8=24 green check. $BRAND" public/assets/illustrations/m5-scene2.png 1344x768
g "Cartoon child reading in school garden, robot mascot with magnifying glass, goat behind gate. $BRAND" public/assets/illustrations/m5-scene3.png 1344x768
g "Cartoon robot mascot holding two story versions grey rough and turquoise shiny. $BRAND" public/assets/illustrations/m6-scene1.png 1344x768
g "Cartoon five star checklist with green checkmarks, robot mascot. $BRAND" public/assets/illustrations/m6-scene2.png 1344x768
g "Cartoon robot mascot presenting portfolio with confetti and badge. $BRAND" public/assets/illustrations/m6-scene3.png 1344x768
echo "=== Audio ==="
t "Hi there! I am Vance, your friendly robot guide. Welcome to StudyVance AI Explorers! Today we start a fun adventure. We will learn what Artificial Intelligence is. We will learn how to stay safe. And we will learn how to think like a real explorer. Are you ready? Let us go!" public/assets/audio/welcome-intro.wav
t "Hello explorer! Here is our big question for today. Can a computer learn to recognise a cat? Let me tell you a secret. Artificial Intelligence, or AI for short, is software that learns from examples. If we show a computer lots of pictures of cats, and we say these are cats, the computer starts to notice patterns. Like pointy ears. Like whiskers. Like a small nose. Then, when we show it a new picture, it can guess. Is this a cat or not? That is how a computer learns. But remember, it is not magic. It only learned from the examples we gave it." public/assets/audio/m1-scene1.wav
t "Not every computer trick is AI. Some things just follow fixed steps that a person wrote down. A calculator follows fixed steps to add numbers. A kitchen timer follows fixed steps to count down. These are ordinary programs. They always do the same thing. But when a computer is trained on lots of animal pictures and then guesses this is a cat, that is AI. When a text tool learns from many stories and then writes a new story, that is also AI. Some products mix ordinary programs and AI together. The big question is: did it learn from examples, or did it just follow fixed steps?" public/assets/audio/m1-scene2.wav
t "Now, the most important rule in our academy. AI can be useful, but it can also make mistakes. A confident answer is not proof. And we must always protect our private information. Never tell an AI tool your real full name. Never share your home address. Never share your phone number. Never share your password. And never share another childs photo. If you want to write a story, use a made-up name, like Pip the robot rabbit. Be kind. Be safe. Be truthful. Now let us practice with a game!" public/assets/audio/m1-scene3.wav
t "A prompt is a question or instruction you give to an AI tool. More words are not always better. What matters is useful details. A great prompt has three parts. First, the TASK. That is what you want the AI to do. Second, the DETAILS. Those are useful specifics. Third, the FORMAT. That is how you want the answer to look. When you use all three parts, the AI is much more likely to give you what you actually wanted." public/assets/audio/m2-scene1.wav
t "Let us build a prompt together. The TASK is: write three short sentences. The DETAILS are: about a made-up robot rabbit helping an animal shelter, for a Grade 4 reader, simple words, friendly tone, no real names. The FORMAT is: three bullet points. Put them together and you get a clear, safe prompt. Now the AI knows exactly what to make, who it is for, and how to lay it out." public/assets/audio/m2-scene2.wav
t "Not every reply follows the request. Reply A says: Animals are found in many places. They can be large or small. People like animals. Reply B says: A robot rabbit carried blankets to the animal shelter. It helped the keeper fill the water bowls. At sunset, every animal had a cosy place to rest. Reply B follows the brief better. Also remember: if you asked for bullet points, a long paragraph does not meet the request." public/assets/audio/m2-scene3.wav
t "A claim is something a person or a computer says is true. Evidence is the information we use to check the claim. The computer says it is true. But is that enough? No! A confident answer is not proof. To be a real AI detective, you must check claims against evidence. Do not just trust them because they sound sure." public/assets/audio/m3-scene1.wav
t "Here are four facts from our Moon fact sheet. Fact A: The Moon reflects sunlight. Fact B: The Moon orbits Earth. Fact C: Earth has one natural moon. Fact D: The Moon has no breathable air for people, so people need life-support equipment. Keep these four facts in mind. You will use them to check five claims next." public/assets/audio/m3-scene2.wav
t "To check a claim, follow four steps. Step one: Read the claim carefully. Step two: Compare it to your evidence. Step three: Decide. Is the claim supported, contradicted, or is there not enough information? Step four: Correct the claim if it is wrong. Remember, asking the same AI again is not independent proof. You still need your own evidence." public/assets/audio/m3-scene3.wav
t "Every good story has four parts. A character, that is who. A setting, that is where. A problem, that is what goes wrong. And a kind solution, that is how it gets fixed. Before you write, plan these four parts. For our practice story, we will use a made-up robot rabbit at an animal shelter. No real names. No magic. And a kind ending." public/assets/audio/m4-scene1.wav
t "Here is a practice draft that breaks the brief. Pip the robot rabbit worked at an animal shelter. One morning, a kittens blanket was missing. Pip shouted at the kitten for losing it. Then a magic wand appeared and made a hundred blankets. The kitten flew into space. Everyone clapped. The brief was: a kind story at an animal shelter, no magic. Can you spot where it breaks the brief? Pip shouts, that is not kind. A magic wand appears, that is magic. The kitten flies into space, that is not a kind or real solution." public/assets/audio/m4-scene2.wav
t "When you create something, you must truthfully say what help you used. Did you use the prepared practice draft? Did a teacher run a live AI for you? Or did you write your own first draft without AI? The app must never claim AI was used if it was not. Your own work matters. Be honest about what is yours and what help you got." public/assets/audio/m4-scene3.wav
t "Should AI give you the answer, or help you find it? If AI just gives you the full answer to copy, you do not learn. But if AI gives you one hint and then lets you try, you build your own skill. A hint is like a stepping stone. It helps you cross without carrying you. The best way to learn is: ask for a hint, try yourself, then check your work." public/assets/audio/m5-scene1.wav
t "Let us check a maths example. 24 divided by 3. The correct answer is 8, because 3 times 8 equals 24. But someone says: 24 divided by 3 equals 7, because 3 times 7 equals 24. Is that right? Let us check. 3 times 7 is 21, not 24. So the method is wrong, even though it sounded confident. Always check the working, not just the final number. Then try a similar problem on your own. 18 divided by 3 equals 6, because 3 times 6 equals 18." public/assets/audio/m5-scene2.wav
t "Here is a short passage. Lebo took a small watering can to the school garden. The soil near the beans felt dry. Lebo watered the soil slowly, then placed a label beside each row. Before leaving, Lebo closed the gate to keep the goats out. Now ask: what felt dry? The soil near the beans. Why close the gate? To keep the goats out. Was the gate left open? No, the passage says Lebo closed it. Does the passage say the watering can was red? No, there is not enough information. Good detectives read carefully and only answer what the passage actually says." public/assets/audio/m5-scene3.wav
t "It is time to finish your story. Read your first draft again. Find at least two sentences you can improve. Maybe make them clearer, kinder, or more descriptive. Keep your first draft and your final draft, so you can see how your thinking grew. Your story should be 6 to 8 sentences long. It should have a made-up character, a setting, a problem, and a kind solution. And at least one matching drawing." public/assets/audio/m6-scene1.wav
t "Before you finish Level 1, let us check five skills on your own. One: can AI make mistakes? Two: which is a safe prompt choice, and which is your password? Three: can you improve Make a story using task, details, and format? Four: can you correct the two moons claim using the Moon fact sheet? Five: can you explain why a hint helps more than copying? These five checks show what you can do on your own." public/assets/audio/m6-scene2.wav
t "When you are ready, show your story portfolio to your tutor. Your portfolio has your first and final drafts, your drawing, and your truthful assistance note. Your tutor will review it and decide if you are ready for Level 2, or if you should practise a bit more. Remember, finishing Level 1 does not automatically mean you are ready for Level 2. That is your tutors decision, based on your evidence. Either way, you are now an AI Explorer!" public/assets/audio/m6-scene3.wav
echo "=== DONE ==="
echo "Images: $(ls public/assets/illustrations/*.png public/assets/avatars/*.png public/assets/badges/*.png public/assets/mascot/*.png 2>/dev/null | wc -l)"
echo "Audio: $(ls public/assets/audio/*.wav 2>/dev/null | wc -l)"
